        <Row
          key={each.id}
          task={each}
          isEditing={editing === each.id}
          onEditStart={() => setEditing(each.id)}
          onEditCancel={() => setEditing(undefined)}
          onSave={(body) => {
            onSave(body)
            setTasks((current) =>
              current.map((other) => (other.id === each.id ? { ...other, text: body.text } : other)),
            )
            setEditing(undefined)
          }}
