=== contexts/guestbook/hooks/useGuestbookEntries.ts
import { useEffect } from 'react'
import {
  keepPreviousData,
  useInfiniteQuery,
  useMutation,
  useQueryClient,
} from '@tanstack/react-query'
import type { UseInfiniteQueryResult, UseMutationResult } from '@tanstack/react-query'

import { client, unwrap } from '@/api/client'
import type { components } from '@/api/schema'
import { firstPageRequest, nextPageRequest } from '@/contexts/guestbook/lib/entryPaging'
import type { GuestbookEntry } from '@/contexts/guestbook/lib/guestbookEntry'

export type GuestbookEntryCreate = components['schemas']['GuestbookEntryCreate']
export type GuestbookEntryUpdate = components['schemas']['GuestbookEntryUpdate']
export type GuestbookEntryPage = components['schemas']['GuestbookEntryPage']

/**
 * Which end of the book to read from. The two words are the contract's, not
 * this module's -- taken from the generated schema so a third order added to
 * the API cannot be missed here.
 */
export type GuestbookEntrySort = components['schemas']['GuestbookEntrySort']

/**
 * What a read of the book asks for -- **the question, and nothing about how
 * much of the answer is on screen**.
 *
 * `limit` used to be a third member and that was the defect: a page size is not
 * part of a question's identity, so asking for a bigger piece looked to the
 * cache like somebody had asked something else. Worse, once the size hit the
 * contract's ceiling it stopped changing, the key stopped moving with it, and
 * pressing "Load more" refetched nothing at all.
 */
export interface GuestbookEntryQuery {
  /** Narrow to entries containing this. Empty means the whole book. */
  search: string
  sort: GuestbookEntrySort
}

/** How much of the answer the address says is on screen. Never part of the key. */
export interface GuestbookEntryPaging {
  /** How many entries the address asks to see. */
  shown: number
  /** How many one press of "Load more" adds. */
  step: number
}

/**
 * The query keys for this resource, in one object.
 *
 * Every mutation below invalidates `all`, so a key written by hand at a call
 * site is a cache that silently stops refreshing. Components never call
 * `client.GET` directly (spec/design/conventions.md § Frontend) -- that rule is
 * what makes this the only place the key shape exists.
 *
 * **`list` takes the question**, so two different searches are two different
 * cache entries rather than one entry that flips between two answers. Without
 * that, going back to a phrase already typed would show the previous phrase's
 * results until the refetch landed.
 */
export const guestbookEntryKeys = {
  all: ['guestbook-entries'] as const,
  list: (query: GuestbookEntryQuery) => ['guestbook-entries', 'list', query] as const,
}

/**
 * One piece of the book, **together with the question it answers**.
 *
 * The second half is the whole point. `keepPreviousData` hands back the
 * previous key's pages while the new ones travel, so a screen reading the
 * phrase from the address and the counts from here would put a new phrase in
 * front of old numbers -- and say "2 matches for “Zzz”" over two entries that
 * match nothing of the sort. The question rides with its own answer.
 *
 * `asked` is the current render's `query`, which is the key the fetch runs
 * under, so the attribution is right by construction rather than by care.
 */
interface AnsweredPage extends GuestbookEntryPage {
  asked: GuestbookEntryQuery
}

/** Everything the screen needs about the list, flattened out of the pieces. */
export interface GuestbookEntryList {
  /** Every entry loaded so far, in the server's order (`BR-04`). */
  entries: GuestbookEntry[]
  /** How many match the question these entries answer. */
  total: number
  /** How many the book holds (`BR-05`). */
  totalAll: number
  /** The question `entries`, `total` and `totalAll` are the answer to. */
  answering: GuestbookEntryQuery
}

/**
 * The book, read a piece at a time, up to as much as the address asks for.
 *
 * `keepPreviousData` is what makes the search box usable: without it every
 * settled phrase replaces the list with the loading state, so the screen
 * flickers empty between searches and the reader loses their place. With it the
 * previous answer stays on screen -- and the caller is told so through
 * `isPlaceholderData`, which is how the screen labels it rather than passing it
 * off as the answer to the newer question.
 *
 * **The address is the source of truth for how much is loaded.** `shown` says
 * how many entries belong on screen; the effect below asks for pieces until
 * that many are there or the book runs out. A press of "Load more" therefore
 * writes the address and nothing else -- one direction of flow, and a reload of
 * the same address restores the same range.
 */
export function useGuestbookEntries(
  query: GuestbookEntryQuery,
  { shown, step }: GuestbookEntryPaging,
): UseInfiniteQueryResult<GuestbookEntryList> {
  const result = useInfiniteQuery({
    queryKey: guestbookEntryKeys.list(query),
    queryFn: async ({ pageParam }): Promise<AnsweredPage> => {
      const page = await unwrap(
        client.GET('/api/guestbook-entries', {
          params: {
            query: {
              // Absent rather than empty: `q=` and no `q` at all mean the same
              // thing to the server, and sending the empty one would put a
              // pointless parameter in every request the screen makes.
              q: query.search === '' ? undefined : query.search,
              sort: query.sort,
              limit: pageParam.limit,
              // Absent at its default for the same reason, and present the
              // moment there is a second piece -- which is the parameter the
              // screen was not using while the endpoint had it all along.
              offset: pageParam.offset === 0 ? undefined : pageParam.offset,
            },
          },
        }),
      )
      return { ...page, asked: query }
    },
    initialPageParam: firstPageRequest(shown),
    getNextPageParam: (lastPage, allPages) =>
      nextPageRequest({
        loaded: allPages.reduce((count, page) => count + page.items.length, 0),
        shown,
        total: lastPage.total,
        step,
      }),
    placeholderData: keepPreviousData,
    select: (data) => {
      const last = data.pages.at(-1)
      return {
        entries: data.pages.flatMap((page) => page.items),
        total: last?.total ?? 0,
        totalAll: last?.total_all ?? 0,
        // The first piece's question, because every piece of one key answers
        // the same one and the first is the one that is always there.
        answering: data.pages[0]?.asked ?? query,
      }
    },
  })

  const loaded = result.data?.entries.length ?? 0
  const { isPlaceholderData, isFetching, hasNextPage, fetchNextPage } = result

  /**
   * Fill the screen up to what the address asks for.
   *
   * One piece per pass, re-entered when that piece lands, and refused while the
   * data on screen belongs to another question -- fetching a second piece of an
   * answer whose first piece has not arrived would put the pieces out of order.
   * It terminates on the book rather than on `shown`: `hasNextPage` goes false
   * at `total`, so an address asking for more entries than exist stops at the
   * last one.
   */
  useEffect(() => {
    if (isPlaceholderData || isFetching || !hasNextPage) return
    if (loaded >= shown) return
    void fetchNextPage()
  }, [isPlaceholderData, isFetching, hasNextPage, fetchNextPage, loaded, shown])

  return result
}

/** Add an entry, then refetch the list. */
export function useCreateGuestbookEntry(): UseMutationResult<
  components['schemas']['GuestbookEntryRead'],
  Error,
  GuestbookEntryCreate
> {
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: (body: GuestbookEntryCreate) =>
      unwrap(client.POST('/api/guestbook-entries', { body })),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: guestbookEntryKeys.all }),
  })
}

/**
 * Change an entry, then refetch the list.
 *
 * The list is refetched rather than patched in place because the server owns
 * `updated_at`, the ordering and both counts: writing the server's answer back
 * into the cached page by hand would work until the day an edit moves the entry
 * out of the current search.
 *
 * **Invalidation is also what keeps the pieces honest.** Refetching an infinite
 * query replays every piece from the first, recomputing each offset over the
 * order as it now stands -- so an entry added or removed while several pieces
 * are on screen shifts the boundaries rather than duplicating an entry across
 * them or dropping one between them.
 */
export function useUpdateGuestbookEntry(): UseMutationResult<
  components['schemas']['GuestbookEntryRead'],
  Error,
  { id: string; body: GuestbookEntryUpdate }
> {
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: GuestbookEntryUpdate }) =>
      unwrap(
        client.PATCH('/api/guestbook-entries/{entry_id}', {
          params: { path: { entry_id: id } },
          body,
        }),
      ),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: guestbookEntryKeys.all }),
  })
}

/** Remove an entry permanently, then refetch the list. */
export function useDeleteGuestbookEntry(): UseMutationResult<void, Error, string> {
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: async (id: string) => {
      await unwrap(
        client.DELETE('/api/guestbook-entries/{entry_id}', {
          params: { path: { entry_id: id } },
        }),
      )
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey: guestbookEntryKeys.all }),
  })
}
=== contexts/guestbook/pages/GuestbookPage.tsx
import { useState } from 'react'
import { useNavigate } from 'react-router-dom'

import { describeProblem, problemOf } from '@/api/problem'
import { DeleteEntryDialog } from '@/contexts/guestbook/components/DeleteEntryDialog'
import { EntryCard } from '@/contexts/guestbook/components/EntryCard'
import { EntryComposer } from '@/contexts/guestbook/components/EntryComposer'
import { EntryToolbar } from '@/contexts/guestbook/components/EntryToolbar'
import { PageFrame } from '@/components/shell/PageFrame'
import { GUESTBOOK_ROUTE } from '@/routes'
import { ErrorState, Skeleton } from '@/components/ui/Feedback'
import { useToast } from '@/components/ui/Toast'
import { useEntryQueryParams } from '@/contexts/guestbook/hooks/useEntryQueryParams'
import {
  useCreateGuestbookEntry,
  useDeleteGuestbookEntry,
  useGuestbookEntries,
  useUpdateGuestbookEntry,
} from '@/contexts/guestbook/hooks/useGuestbookEntries'
import {
  READ_FAILED_LABEL,
  describeEmpty,
  describeResult,
  entryCountLabel,
  loadMoreLabel,
} from '@/contexts/guestbook/lib/entryListCopy'
import type { GuestbookEntry } from '@/contexts/guestbook/lib/guestbookEntry'

/**
 * `S-01` -- the only screen in this application.
 *
 * One column: write at the top, narrow in the middle, read below. Four
 * operations and no second address for any of them -- a guest book is one thing
 * a person looks at, and an edit on its own URL would be a screen that exists
 * only to hold a form the card already has room for.
 *
 * Every request's failure is shown where the request was started: the list's
 * failure replaces the list, a write's failure is a toast over a card that still
 * holds what was typed. A write that loses the text on failure is a write people
 * do not retry.
 */

/** How many entries the first page shows, and how many "Load more" adds. */
const PAGE_STEP = 4

/** How long the search box waits for typing to stop before it asks the server. */
const SEARCH_SETTLE_MS = 250

export function GuestbookPage() {
  /**
   * The question lives in the address, not in this component
   * (`spec/design/conventions.md` § Frontend). A result nobody can link to is a
   * result nobody can send, and a search that a refresh forgets is a search
   * somebody has to type twice.
   */
  const { typed, search, sort, shown, onSearchChange, onSortChange, onShownChange } =
    useEntryQueryParams(PAGE_STEP, SEARCH_SETTLE_MS)

  const [editingId, setEditingId] = useState<string | undefined>(undefined)
  const [confirmingDelete, setConfirmingDelete] = useState<GuestbookEntry | undefined>(undefined)

  /**
   * Bumped after every **successful** add, to remount the composer empty.
   *
   * A counter rather than clearing the fields, because the composer owns its own
   * inputs and their touched state -- clearing from the outside would need this
   * page to hold all of it, which is the coupling `EntryComposer` exists to
   * avoid. Only on success, deliberately: a failed write must leave the text
   * where it was, because retrying otherwise means typing it again.
   */
  const [writes, setWrites] = useState(0)

  const navigate = useNavigate()
  const page = useGuestbookEntries({ search, sort }, { shown, step: PAGE_STEP })
  const create = useCreateGuestbookEntry()
  const update = useUpdateGuestbookEntry()
  const remove = useDeleteGuestbookEntry()
  const toast = useToast()

  const entries = page.data?.entries ?? []
  const total = page.data?.total ?? 0
  const totalAll = page.data?.totalAll ?? 0

  /**
   * The list on screen answers an older question than the address does.
   *
   * `keepPreviousData` is what puts it there, and saying so is the other half of
   * that decision: entries kept on screen without a word about it are entries
   * the screen is passing off as the answer to the phrase in the box.
   */
  const isStale = page.isPlaceholderData
  const remaining = total - entries.length

  function reportFailure(error: unknown) {
    toast.push(describeProblem(problemOf(error)).detail, 'error')
  }

  function handleCreate(values: { author: string; message: string }) {
    create.mutate(values, {
      onSuccess: () => {
        setWrites((count) => count + 1)
        // Back to the top of an unfiltered book, because that is where the entry
        // just written is -- posting into a search that does not match it would
        // otherwise look like the write having failed. The navigation alone:
        // the search box follows the address now, so clearing it by hand here
        // would be a second way of saying the same thing, and the two could
        // disagree. It used to need both, which was the coupling showing.
        navigate(GUESTBOOK_ROUTE, { replace: true })
        toast.push('Entry posted.', 'success')
      },
      onError: reportFailure,
    })
  }

  function handleSave(entry: GuestbookEntry, values: { author: string; message: string }) {
    update.mutate(
      { id: entry.id, body: values },
      {
        onSuccess: () => {
          // Only the editor that sent this save, the way the delete path below
          // has always done it: an answer to one operation must not close an
          // editor somebody opened over a different entry in the meantime.
          setEditingId((current) => (current === entry.id ? undefined : current))
          toast.push('Entry updated.', 'success')
        },
        onError: reportFailure,
      },
    )
  }

  function handleConfirmDelete() {
    if (confirmingDelete === undefined) return
    const doomed = confirmingDelete
    remove.mutate(doomed.id, {
      onSuccess: () => {
        // An entry being edited that somebody just deleted would leave the
        // editor writing to an id that no longer resolves, and the save would
        // refuse with a 404 nobody could act on.
        if (editingId === doomed.id) setEditingId(undefined)
        setConfirmingDelete(undefined)
        toast.push('Entry deleted.', 'success')
      },
      onError: (error) => {
        setConfirmingDelete(undefined)
        reportFailure(error)
      },
    })
  }

  return (
    <PageFrame
      title="Leave a note"
      lede="No account, no sign-in. Write something, and it appears below straight away. Anyone can edit or remove an entry."
      meta={page.isSuccess ? entryCountLabel(totalAll) : undefined}
    >
      <EntryComposer key={`new-${writes}`} onSubmit={handleCreate} isPending={create.isPending} />

      <EntryToolbar
        search={typed}
        onSearchChange={onSearchChange}
        sort={sort}
        onSortChange={onSortChange}
        isStale={isStale}
        resultLabel={
          page.isError
            ? READ_FAILED_LABEL
            : page.data !== undefined
              ? describeResult({
                  // The phrase the numbers came back for, which is not the one
                  // in the address until the screen has settled.
                  search: page.data.answering.search,
                  shown: entries.length,
                  total,
                  settled: !isStale,
                })
              : ' '
        }
      />

      {page.isPending && <EntrySkeletons count={PAGE_STEP} />}

      {page.isError && (
        <ErrorState problem={problemOf(page.error)} onRetry={() => void page.refetch()} />
      )}

      {page.data !== undefined && !page.isError && (
        <>
          <section className="flex flex-col gap-3" aria-busy={isStale}>
            {entries.map((entry) => (
              <EntryCard
                key={entry.id}
                entry={entry}
                isEditing={editingId === entry.id}
                onEditStart={() => setEditingId(entry.id)}
                onEditCancel={() => setEditingId(undefined)}
                onSave={(values) => handleSave(entry, values)}
                onDelete={() => setConfirmingDelete(entry)}
                // Bound to the operation, not to whichever editor is open: the
                // marker belongs on the entry whose PATCH is actually in flight.
                isSaving={update.isPending && update.variables?.id === entry.id}
                isSaveInFlight={update.isPending}
                isDeleting={remove.isPending && confirmingDelete?.id === entry.id}
              />
            ))}
          </section>

          {entries.length === 0 && (
            <div className="rounded-card border border-dashed border-line px-5 py-14 text-center text-body text-muted">
              {describeEmpty(search)}
            </div>
          )}

          {page.hasNextPage === true && !isStale && (
            <div className="flex justify-center pt-7">
              <button
                type="button"
                onClick={() => onShownChange(entries.length + PAGE_STEP)}
                className="cursor-pointer rounded-control border border-hairline bg-card px-5.5 py-2.5 text-sm text-ink hover:border-accent hover:text-accent"
              >
                {loadMoreLabel(remaining, PAGE_STEP)}
              </button>
            </div>
          )}
        </>
      )}

      {confirmingDelete !== undefined && (
        <DeleteEntryDialog
          entry={confirmingDelete}
          isPending={remove.isPending}
          onConfirm={handleConfirmDelete}
          onCancel={() => setConfirmingDelete(undefined)}
        />
      )}
    </PageFrame>
  )
}

/**
 * Cards in outline while the first page loads.
 *
 * Card-shaped and not a spinner, because the height is reserved: the content
 * does not jump under the cursor at the moment it arrives. A spinner over an
 * empty column would also be indistinguishable from a book with nothing in it,
 * which is the one thing this screen has to be able to say clearly.
 */
function EntrySkeletons({ count }: { count: number }) {
  return (
    <div className="flex flex-col gap-3" role="status" aria-label="Loading entries">
      {Array.from({ length: count }, (_, index) => (
        <div key={index} className="rounded-card border border-hairline bg-card px-5 py-5">
          <Skeleton className="h-3 w-40" />
          <Skeleton className="mt-3.5 h-2.5 w-full" />
          <Skeleton className="mt-2 h-2.5 w-4/5" />
        </div>
      ))}
    </div>
  )
}
=== api/problem.ts
/**
 * One error shape for the whole frontend.
 *
 * The target contract is RFC 9457 problem details (`type` / `title` /
 * `status` / `detail`, plus `errors` for field-level validation). The Python
 * service currently answers with FastAPI's own `{"detail": ...}` bodies --
 * a bare string for `HTTPException`, and a list of Pydantic error objects
 * for a 422 -- so `toProblem` normalises all three into the RFC shape at the
 * single point where responses are unwrapped.
 *
 * Everything downstream (pages, components, error boundaries) sees only
 * `Problem`. When the backend starts emitting real problem details, the
 * legacy branches below are the only code that becomes dead.
 */

export const PROBLEM_BLANK = 'about:blank'

/** A field-level validation failure, keyed by dotted field path. */
export type FieldErrors = Record<string, string[]>

export interface Problem {
  type: string
  title: string
  status: number
  detail?: string
  errors?: FieldErrors
}

/** FastAPI's 422 body: `{"detail": [{loc, msg, type}, ...]}`. */
interface PydanticError {
  loc?: (string | number)[]
  msg?: string
  type?: string
}

function isPydanticErrorList(value: unknown): value is PydanticError[] {
  return (
    Array.isArray(value) &&
    value.every((entry) => typeof entry === 'object' && entry !== null && 'msg' in entry)
  )
}

/**
 * A refusal: `{"detail": {"code", "message", ...}}`.
 *
 * The shape `app/platform/schemas/refusals.py` declares and every route that can
 * refuse names in its `responses=`, so the generated contract carries it as
 * `RefusalDetail`. A stable `code` a screen can branch on, and a finished sentence
 * in `message` a person can read; the codes and their sentences are frozen in
 * `contracts/openapi/guestbook.yaml` (`x-refusals`) and stated in
 * `spec/design/api.md` § Refusals. Extra keys (`id`, ...) ride along untouched.
 */
interface RefusalDetail {
  code: string
  message: string
}

function isRefusalDetail(value: unknown): value is RefusalDetail {
  return (
    typeof value === 'object' &&
    value !== null &&
    !Array.isArray(value) &&
    typeof (value as RefusalDetail).message === 'string' &&
    typeof (value as RefusalDetail).code === 'string'
  )
}

/** The `type` URN a refusal is given, so a screen can branch without matching prose. */
export function refusalType(code: string): string {
  return `urn:app:refusal:${code}`
}

/**
 * Group Pydantic's flat error list by field path.
 *
 * `loc` arrives as `["body", "imported_by"]` -- the first element names the
 * request part, not the field, so it is dropped. A `loc` of length <= 1
 * describes the request as a whole and lands under `_`.
 */
function toFieldErrors(errors: PydanticError[]): FieldErrors {
  const grouped: FieldErrors = {}
  for (const error of errors) {
    const path = (error.loc ?? []).slice(1)
    const key = path.length > 0 ? path.join('.') : '_'
    const bucket = grouped[key] ?? (grouped[key] = [])
    bucket.push(error.msg ?? 'Invalid value')
  }
  return grouped
}

const TITLE_BY_STATUS: Record<number, string> = {
  400: 'Bad request',
  401: 'Session expired',
  403: 'Not allowed',
  404: 'Not found',
  409: 'Conflict',
  422: 'That did not pass validation',
  500: 'Server error',
  502: 'Service unavailable',
  503: 'Service unavailable',
  504: 'The request timed out',
}

function titleFor(status: number): string {
  return TITLE_BY_STATUS[status] ?? (status >= 500 ? 'Server error' : 'The request failed')
}

/** Normalise any error body into a `Problem`. */
export function toProblem(status: number, body: unknown): Problem {
  const base: Problem = { type: PROBLEM_BLANK, title: titleFor(status), status }

  if (typeof body !== 'object' || body === null) {
    return typeof body === 'string' && body !== '' ? { ...base, detail: body } : base
  }

  const record = body as Record<string, unknown>

  // Already RFC 9457.
  if (typeof record.title === 'string' && typeof record.status === 'number') {
    return {
      type: typeof record.type === 'string' ? record.type : PROBLEM_BLANK,
      title: record.title,
      status: record.status,
      detail: typeof record.detail === 'string' ? record.detail : undefined,
      errors: (record.errors as FieldErrors | undefined) ?? undefined,
    }
  }

  const { detail } = record

  if (typeof detail === 'string') return { ...base, detail }

  if (isPydanticErrorList(detail)) {
    const errors = toFieldErrors(detail)
    return {
      ...base,
      detail: 'Correct the highlighted fields and send again.',
      errors,
    }
  }

  // A refusal. Checked after the Pydantic list because a 422 can be either and
  // only the shape tells them apart -- a list is field-level validation, an
  // object is a refusal with a code.
  //
  // Without this branch the whole class fell through to `base`, so `detail` was
  // undefined and the screen rendered its "the service returned no details"
  // fallback while the service had in fact returned a finished sentence.
  if (isRefusalDetail(detail)) {
    return { ...base, type: refusalType(detail.code), detail: detail.message }
  }

  return base
}

/** What an error surface needs to render a `Problem`. Prose, not status codes. */
export interface ProblemCopy {
  title: string
  detail: string
  /** Field path -> messages, ready to list. Empty when there are none. */
  fields: [field: string, messages: string[]][]
  /** False when retrying cannot help, so no retry action is offered. */
  retryable: boolean
}

/**
 * Turn a `Problem` into the sentences a screen shows.
 *
 * Here rather than in `components/ui/Feedback`, which renders it: reading a
 * status code and deciding what it means to an operator is knowledge of this
 * API, and `spec/design/conventions.md` § Frontend keeps that out of the shared
 * primitives. `ErrorState`
 * is handed finished prose and paints it.
 *
 * A 404 is described as its own thing rather than as a generic failure:
 * "somebody else deleted this" and "this broke" are different facts, and only
 * one of them is worth retrying. It is the refusal this API emits most, because
 * every route that takes an id can produce it.
 */
export function describeProblem(problem: Problem): ProblemCopy {
  if (problem.status === 404) {
    return {
      title: 'That is gone',
      detail:
        problem.detail ??
        'What you asked for does not exist. Somebody else may have deleted it.',
      fields: [],
      // Retrying re-asks for something that is gone, so the retry action goes
      // away with the refusal that means it cannot come back.
      retryable: false,
    }
  }

  return {
    title: problem.title,
    detail:
      problem.detail ??
      'The service returned no detail. Try again, or check whether the backend answers on /api/health.',
    // Listed because a 422 is almost always a fixable form problem, and naming
    // the field is the whole of the fix.
    fields: Object.entries(problem.errors ?? {}),
    retryable: true,
  }
}

/**
 * A `Problem` thrown as an Error so TanStack Query treats it as a failure.
 *
 * `message` carries `detail ?? title` because that is what generic error
 * surfaces (an error boundary, a console log) will print; components that
 * need structure read `.problem` instead.
 */
export class ApiError extends Error {
  readonly problem: Problem

  constructor(problem: Problem) {
    super(problem.detail ?? problem.title)
    this.name = 'ApiError'
    this.problem = problem
  }

  get status(): number {
    return this.problem.status
  }
}

/** The problem to show for an error of unknown provenance. */
export function problemOf(error: unknown): Problem {
  if (error instanceof ApiError) return error.problem
  if (error instanceof Error) {
    return {
      type: PROBLEM_BLANK,
      title: 'Could not reach the service',
      status: 0,
      detail: error.message,
    }
  }
  return { type: PROBLEM_BLANK, title: 'Unknown error', status: 0 }
}
