        {isEditing ? (
          <TodoTaskEditor
            // Remounted per task, so an editor always starts from what that task
            // holds now rather than from the last one's text.
            key={task.id}
            task={task}
            isSaving={isSaving}
            refusal={saveRefusal}
            onSave={onSave}
            onCancel={onEditCancel}
          />
        ) : (
