          >
            {task.text}
          </label>
        )}
      </div>

      {isMarking && <span className="shrink-0 text-meta leading-6 text-faint">Saving…</span>}

      <span className="flex shrink-0 gap-3.5">
        <button
          ref={editRef}
          type="button"
          onClick={onEditStart}
