const ACTION =
  'cursor-pointer border-0 bg-transparent p-0 text-meta leading-6 text-faint disabled:cursor-default disabled:opacity-50'

export function TodoTaskRow({
  task,
  isEditing,
  onEditStart,
  onEditCancel,
  onSave,
  onMark,
  onDelete,
  isMarking = false,
  isSaving = false,
