    // unlocks it -- so it is handed over here once the button can take it.
    if (focusIsFree()) deleteRef.current?.focus()
  })

  const editWord = isEditing ? 'Editing' : 'Edit'
  const deleteWord = isDeleting ? 'Deleting…' : 'Delete'

  return (
